create table public.billing_customers (user_id uuid primary key references auth.users(id) on delete cascade, stripe_customer_id text not null unique, created_at timestamptz not null default now());
create table public.billing_subscriptions (stripe_subscription_id text primary key, user_id uuid not null references auth.users(id) on delete cascade, stripe_customer_id text not null references public.billing_customers(stripe_customer_id), status text not null, price_id text not null, current_period_end timestamptz, updated_at timestamptz not null default now());
create index billing_subscriptions_user_idx on public.billing_subscriptions(user_id,updated_at desc);
create table public.billing_events (event_id text primary key, received_at timestamptz not null default now());
alter table public.billing_customers enable row level security; alter table public.billing_subscriptions enable row level security; alter table public.billing_events enable row level security;
create policy customer_read on public.billing_customers for select to authenticated using(user_id=(select auth.uid()));
create policy subscription_read on public.billing_subscriptions for select to authenticated using(user_id=(select auth.uid()));
grant select on public.billing_customers,public.billing_subscriptions to authenticated;
grant select,insert,update on public.billing_customers to service_role;
grant select on public.billing_subscriptions to service_role;
create function public.record_billing_subscription(p_event text,p_user uuid,p_customer text,p_subscription text,p_status text,p_price text,p_period timestamptz) returns boolean language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.billing_customers where user_id=p_user and stripe_customer_id=p_customer) then raise exception 'Customer ownership mismatch'; end if; insert into public.billing_events(event_id) values(p_event) on conflict do nothing; if not found then return false; end if; insert into public.billing_subscriptions(stripe_subscription_id,user_id,stripe_customer_id,status,price_id,current_period_end) values(p_subscription,p_user,p_customer,p_status,p_price,p_period) on conflict(stripe_subscription_id) do update set status=excluded.status,price_id=excluded.price_id,current_period_end=excluded.current_period_end,updated_at=now() where public.billing_subscriptions.user_id=excluded.user_id and public.billing_subscriptions.stripe_customer_id=excluded.stripe_customer_id; if not found then raise exception 'Subscription ownership mismatch'; end if; return true; end $$;
revoke all on function public.record_billing_subscription(text,uuid,text,text,text,text,timestamptz) from public;
grant execute on function public.record_billing_subscription(text,uuid,text,text,text,text,timestamptz) to service_role;
